      /* W3: Change ALs to R. */
      if (this_type == FRIBIDI_TYPE_AL)
        {
          RL_TYPE (pp) = FRIBIDI_TYPE_RTL;
          w4 = true;
          prev_type_orig = FRIBIDI_TYPE_ON;
          continue;
